    assertEquals(expertimentIdTwo, experimentSummaryModelList.get(0).getExperimentId());
    filters.remove(DBConstants.ExperimentSummary.FROM_DATE);
    filters.remove(DBConstants.ExperimentSummary.TO_DATE);
